SELECT 
    'CBMPI' ORGAO,
    ANTERIOR.CHAVE_FOLHA_MES03,
    ANTERIOR.MATRICULA,
    ANTERIOR.NOME,
    ANTERIOR.DIVISAO,
    ANTERIOR.SITUACAO,
    ANTERIOR.CARGO_ESPECIALIDADE_INGRESSO,
    ANTERIOR.CARGO_ESPECIALIDADE_REFERENCIA,
    ANTERIOR.NOME_REFERENCIA_MES03,
    ANTERIOR.COD_RUBRICA_MES03,
    ANTERIOR.VALOR_CALCULADO_MES03,
    ATUAL.CHAVE_FOLHA_MES04,
    ATUAL.MATRICULA,
    ATUAL.DIVISAO,
    ATUAL.CARGO_ESPECIALIDADE_INGRESSO,
    ATUAL.CARGO_ESPECIALIDADE_REFERENCIA,
    ATUAL.NOME_REFERENCIA_MES04,
    ATUAL.COD_RUBRICA_MES04,
    ATUAL.VALOR_CALCULADO_MES04
FROM
    (
    SELECT
        FO.CHAVE_FOLHA CHAVE_FOLHA_MES03,
        FF.COD_INSTITUCIONAL MATRICULA,
        HN.NOME,
        PD.NOME_DIVISAO DIVISAO,
        PS.NOME_SITUACAO SITUACAO,
        R.COD_RUBRICA COD_RUBRICA_MES03,
        NVL(CF2.NOME_CATEGORIA_FUNCIONAL, CE2.NOME_ESPECIALIDADE) CARGO_ESPECIALIDADE_INGRESSO,
        NVL(CF.NOME_CATEGORIA_FUNCIONAL, CE.NOME_ESPECIALIDADE) CARGO_ESPECIALIDADE_REFERENCIA,
        FR.VALOR_CALCULADO VALOR_CALCULADO_MES03,
        CR.NOME_REFERENCIA NOME_REFERENCIA_MES03
    FROM
        SW_CBMPI.FOLHA FO
        JOIN SW_CBMPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
        JOIN SW_CBMPI.FOLHA_FUNC_RUBRICA FR ON FR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
        JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FR.ID_RUBRICA
        JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
        JOIN SW_CBMPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
        JOIN SW_CBMPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
        JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
        JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
        LEFT JOIN SW_CBMPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
        LEFT JOIN SW_CBMPI.FUNCIONARIO_REFERENCIA FRR ON FRR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FRR.DATA_TERMINO IS NULL
        LEFT JOIN SW_CBMPI.RHB_CARREIRA_CATEG_FUNCIONAL CF ON CF.ID_CATEGORIA_FUNCIONAL = FI.ID_CATEGORIA_FUNCIONAL
        LEFT JOIN SW_CBMPI.RHB_CARREIRA_CATEG_FUNCIONAL CF2 ON CF2.ID_CATEGORIA_FUNCIONAL = FRR.ID_CATEGORIA_FUNCIONAL
        LEFT JOIN SW_CBMPI.RHB_CARREIRA_CATEG_ESPECIALID CE ON CE.ID_ESPECIALIDADE = FI.ID_ESPECIALIDADE
        LEFT JOIN SW_CBMPI.RHB_CARREIRA_CATEG_ESPECIALID CE2 ON CE2.ID_ESPECIALIDADE = FRR.ID_ESPECIALIDADE
        LEFT JOIN SW_CBMPI.RHB_CARREIRA_REFERENCIA CR ON CR.ID_REFERENCIA = FRR.ID_REFERENCIA
    WHERE
        FO.MES = 3
        AND FO.ANO = 2026
        AND R.COD_RUBRICA IN (121003,131003,141003,151003,111001,111002,121002,131002,141002,151002,121001,121011,131001,131012,141005,151005)
        AND FO.CHAVE_FOLHA = '04/2026-100'
    ) ANTERIOR
    LEFT JOIN (
    SELECT
        FO.CHAVE_FOLHA CHAVE_FOLHA_MES04,
        FF.COD_INSTITUCIONAL MATRICULA,
        HN.NOME,
        PD.NOME_DIVISAO DIVISAO,
        PS.NOME_SITUACAO SITUACAO,
        NVL(CF2.NOME_CATEGORIA_FUNCIONAL, CE2.NOME_ESPECIALIDADE) CARGO_ESPECIALIDADE_INGRESSO,
        NVL(CF.NOME_CATEGORIA_FUNCIONAL, CE.NOME_ESPECIALIDADE) CARGO_ESPECIALIDADE_REFERENCIA,
        R.COD_RUBRICA COD_RUBRICA_MES04,
        FR.VALOR_CALCULADO VALOR_CALCULADO_MES04,
        CR.NOME_REFERENCIA NOME_REFERENCIA_MES04
    FROM
        SW_CBMPI.FOLHA FO
        JOIN SW_CBMPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
        JOIN SW_CBMPI.FOLHA_FUNC_RUBRICA FR ON FR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
        JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FR.ID_RUBRICA
        JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
        JOIN SW_CBMPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
        JOIN SW_CBMPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
        JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
        JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
        LEFT JOIN SW_CBMPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
        LEFT JOIN SW_CBMPI.FUNCIONARIO_REFERENCIA FRR ON FRR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FRR.DATA_TERMINO IS NULL
        LEFT JOIN SW_CBMPI.RHB_CARREIRA_CATEG_FUNCIONAL CF ON CF.ID_CATEGORIA_FUNCIONAL = FI.ID_CATEGORIA_FUNCIONAL
        LEFT JOIN SW_CBMPI.RHB_CARREIRA_CATEG_FUNCIONAL CF2 ON CF2.ID_CATEGORIA_FUNCIONAL = FRR.ID_CATEGORIA_FUNCIONAL
        LEFT JOIN SW_CBMPI.RHB_CARREIRA_CATEG_ESPECIALID CE ON CE.ID_ESPECIALIDADE = FI.ID_ESPECIALIDADE
        LEFT JOIN SW_CBMPI.RHB_CARREIRA_CATEG_ESPECIALID CE2 ON CE2.ID_ESPECIALIDADE = FRR.ID_ESPECIALIDADE
        LEFT JOIN SW_CBMPI.RHB_CARREIRA_REFERENCIA CR ON CR.ID_REFERENCIA = FRR.ID_REFERENCIA
    WHERE
        FO.MES = 4
        AND FO.ANO = 2026
        AND R.COD_RUBRICA IN (121003,131003,141003,151003,111001,111002,121002,131002,141002,151002,121001,121011,131001,131012,141005,151005)
        AND FO.CHAVE_FOLHA = '04/2026-100'
    ) ATUAL ON ATUAL.MATRICULA = ANTERIOR.MATRICULA AND ATUAL.COD_RUBRICA_MES04 = ANTERIOR.COD_RUBRICA_MES03 AND SUBSTR(ATUAL.CHAVE_FOLHA_MES04, 9) = SUBSTR(ANTERIOR.CHAVE_FOLHA_MES03, 9)

UNION ALL
